    local autoMine = import(S(448))(import)
    local autoPlace = import(S(475))(import)
    local autoChest = import(S(321))(import)
    local autoSell = import(S(23))(import)
    local autoUpgrade = import(S(338))(import)
    scheduler.RegisterStandalone(S(247), autoMine.Step, autoMine.IsEnabled)
    scheduler.RegisterStandalone(S(485), autoUpgrade.Step, autoUpgrade.IsEnabled)
    scheduler.RegisterExclusive(S(385), autoPlace.Step, autoPlace.IsEnabled, autoPlace.IsBusy)
    scheduler.RegisterExclusive(S(74), autoChest.Step, autoChest.IsEnabled, autoChest.IsBusy)
    scheduler.RegisterExclusive(S(351), autoSell.Step, autoSell.IsEnabled, autoSell.IsBusy)
    scheduler.Start()
    local farmTab = window:AddTab(S(540), S(19))
