    local checkBtn
    checkBtn = debugCard:AddButton(S(523), function()
        local plot = getCurrentPlot()
        if not plot then
            checkBtn.Text = S(240)
            log(S(423))
            return
        end
        local parts = getPlotParts(plot)
        local nodeCount = parts.Nodes and #parts.Nodes:GetChildren() or 0
        local holderCount = parts.Holders and #parts.Holders:GetChildren() or 0
        checkBtn.Text = plot.Name
        log(string.format(
            S(477),
            plot.Name, nodeCount, holderCount
        ))
    end)
    local dumpCard = farmTab:AddCard(
        S(25),
        S(50)
    )
    local dumpBtn
    dumpBtn = dumpCard:AddButton(S(299), function()
        local plot = getCurrentPlot()
        if not plot then
            dumpBtn.Text = S(166)
            return
        end
        local ok, err = log(S(541))
        if not ok then
            dumpBtn.Text = S(320)
            dumpCard:SetSubtitle(S(430) .. tostring(err))
            return
        end
        local parts = getPlotParts(plot)
        local firstNode = parts.Nodes and parts.Nodes:GetChildren()[1]
        if firstNode then
            log(S(407) .. firstNode.Name .. S(136))
            dumpInstance(firstNode, log)
        else
            log(S(416))
        end
        local firstHolder = parts.Holders and parts.Holders:GetChildren()[1]
        if firstHolder then
            log(S(186) .. firstHolder.Name .. S(404))
            dumpInstance(firstHolder, log)
        else
            log(S(387))
        end
        dumpBtn.Text = S(221)
    end)
    local toolDumpCard = farmTab:AddCard(
        S(21),
        S(461)
    )
    local toolDumpBtn
    toolDumpBtn = toolDumpCard:AddButton(S(302), function()
        local backpack = Players.LocalPlayer:FindFirstChild(S(91))
        local tool = backpack and backpack:FindFirstChildWhichIsA(S(144))
        if not tool then
            toolDumpBtn.Text = S(115)
            return
        end
        log(S(178) .. tool.Name .. S(529))
        for attrName, attrValue in pairs(tool:GetAttributes()) do
            log(S(29) .. attrName .. S(177) .. tostring(attrValue))
        end
        dumpInstance(tool, log)
        toolDumpBtn.Text = S(61)
    end)
    local remoteDumpCard = farmTab:AddCard(
        S(456),
        S(334)
    )
    local remoteDumpBtn
    remoteDumpBtn = remoteDumpCard:AddButton(S(53), function()
        local count = dumpRemotes()
        remoteDumpBtn.Text = count .. S(346)
    end)
    local sellCardsDumpCard = farmTab:AddCard(
        S(366),
        S(522)
    )
    local sellCardsDumpBtn
    sellCardsDumpBtn = sellCardsDumpCard:AddButton(S(10), function()
        local count = dumpSellCards()
        sellCardsDumpBtn.Text = count .. S(92)
    end)
    local guiDumpCard = farmTab:AddCard(
        S(83),
        S(49)
    )
    local guiDumpBtn
    guiDumpBtn = guiDumpCard:AddButton(S(537), function()
        dumpGui()
        guiDumpBtn.Text = S(405)
    end)
    local chestDumpCard = farmTab:AddCard(
        S(202),
        S(196)
    )
    local chestDumpBtn
    chestDumpBtn = chestDumpCard:AddButton(S(317), function()
        local count = dumpChest()
        chestDumpBtn.Text = count .. S(465)
    end)
    local settingsTab = window:AddTab(S(525), S(463))
    persistentToggle(
        settingsTab:AddCard(S(436), S(515)),
        S(157),
        antiAfk.SetEnabled
    )
    persistentToggle(
