            S(476)
        ),
        S(422),
        interactionLogger.SetEnabled
    )
    local savedScale = config.Get(S(505), 100)
    settingsTab:AddSlider(S(35), S(261), 50, 150, savedScale, function(value)
        config.Set(S(276), value)
        window:SetScale(value)
    end)
    window:SetScale(savedScale)
    local savedLanguage = config.Get(S(286), 1)
    settingsTab:AddSegmented({ S(492), S(378), S(222) }, savedLanguage, function(index, value)
        local code = ({ S(208), S(79), S(55) })[index]
        config.Set(S(474), index)
        i18n.SetLanguage(code)
    end)
    i18n.SetLanguage(({ S(391), S(22), S(439) })[savedLanguage] or S(66))
    log(S(229) .. config.Path())
    window:OnDestroy(function()
        scheduler.Stop()
        autoMine.SetEnabled(false)
        autoPlace.SetEnabled(false)
        autoChest.SetEnabled(false)
        antiAfk.SetEnabled(false)
        interactionLogger.SetEnabled(false)
        autoSell.SetEnabled(false)
        autoUpgrade.SetEnabled(false)
    end)
end
